<?php require 'app_core.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']??'');$st=db()->prepare('SELECT id,name,email FROM users WHERE email=? AND active=1 LIMIT 1');$st->execute([$email]);$u=$st->fetch();if($u)send_reset_email($u);$msg='Si el correo está registrado, recibirá un enlace de recuperación.';}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css?v=5.0"><title>Recuperar contraseña</title></head><body class="login"><form method="post" class="login-card"><h1>Recuperar contraseña</h1><p>Ingrese el correo registrado en su cuenta.</p><?php if($msg):?><div class="ok"><?=h($msg)?></div><?php endif;?><label>Correo<input type="email" name="email" required></label><button class="login-button">Enviar enlace seguro</button><a href="login.php">← Volver al ingreso</a></form></body></html>
